const L = eval(pm.collectionVariables.get('lib'));
// Poll `path` until `n` consecutive answers satisfy `pred`. With 2 replicas behind round-robin, n consecutive
// good answers mean that BOTH replicas hold the data (reads are local: no forwarding between FO replicas).
const until = async (role, path, pred, o = {}) => {
  const n = o.n || 6, end = Date.now() + (o.ms || 30000); let ok = 0, last;
  while (Date.now() < end) {
    last = await L.call('GET', path, null, role, o.base, o.h);
    let good = false; try { good = !!pred(last); } catch (e) {}
    ok = good ? ok + 1 : 0;
    if (ok >= n) return {ok: true, last};
    await L.sleep(good ? 150 : 1000);
  }
  return {ok: false, last};
};
const r = await until('BACKOFFICE', '/api/airports/' + pm.environment.get('e2Iata'), x => x.code === 200, {base: pm.environment.get('gateway2'), h: {'X-P2P-Hops': '1'}});
pm.test('Gateway 2 answers 200 on 6 consecutive reads WITHOUT P2P forwarding (event applied by RabbitMQ)', () => pm.expect(r.ok, 'last status ' + r.last.code).to.be.true);

